(()=>{'use strict';if(!['BL-05-02','BL-05-03'].includes(window.DEMO_PAGE?.id))return;const table=document.querySelector('.kodo-art-table'),body=table?.querySelector('.kodo-art-table-tbody'),head=table?.querySelector('.kodo-art-table-thead .kodo-art-table-row');if(!body||!head||body.querySelector('.kodo-art-table-row:not(.kodo-art-table-measure-row)'))return;const row=document.createElement('div');row.className='kodo-art-table-row';row.dataset.localDemoTemplate='true';row.style.height='32px';row.style.display='flex';let totalWidth=0;for(const header of head.children){const cell=document.createElement('div');cell.className=[...header.classList].filter(x=>!x.includes('header')).join(' ');if(!cell.classList.contains('kodo-art-table-cell'))cell.classList.add('kodo-art-table-cell');cell.style.cssText=header.style.cssText;cell.style.height='32px';const width=header.getBoundingClientRect().width;totalWidth+=width;cell.style.width=width+'px';cell.style.minWidth=width+'px';cell.style.flex='0 0 '+width+'px';cell.style.display='flex';cell.style.alignItems='center';const name=header.textContent.trim();if(name==='操作'){for(const label of ['编辑','操作']){const button=document.createElement('button');button.type='button';button.textContent=label;cell.append(button);}}else cell.textContent=/编号|编码|单号/.test(name)?'DEMO-0001':/名称|供应商|客户/.test(name)?'演示条目 A':/状态/.test(name)?'进行中':name?'—':'';row.append(cell);}row.style.width=totalWidth+'px';body.append(row);})();
